<?php declare(strict_types=1); $this->layout('layouts/default',compact('title','productName','activeProduct','currentPage')); ?>
<main class="erp-page erp-page-pending"><nav class="erp-breadcrumb"><a href="/erp">ERP</a><span>/</span><span>Pendências</span></nav>
<?php $this->insert('components/erp-page-header',['heading'=>'Pendências operacionais','description'=>'Acompanhe dados cadastrais que ainda exigem uma ação.','kicker'=>'MOVES · ERP']); ?>
<form method="get" action="/erp/pending" class="erp-filter-bar" role="search"><label>Condomínio<select name="condominium_id"><option value="">Todos</option><?php foreach($condominiums as $condominium): ?><option value="<?= (int)$condominium['id'] ?>" <?= (string)($filters['condominium_id']??'')===(string)$condominium['id']?'selected':'' ?>><?= $this->e((string)$condominium['legal_name']) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="">Todos os status</option><?php foreach(['pending'=>'Pendente','in_progress'=>'Em andamento','done'=>'Resolvida'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($filters['status']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Prioridade<select name="priority"><option value="">Todas</option><?php foreach(['low'=>'Baixa','normal'=>'Normal','high'=>'Alta','urgent'=>'Urgente'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($filters['priority']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Responsável<select name="responsible"><option value="">Todos</option><option value="unassigned" <?= ($filters['responsible']??'')==='unassigned'?'selected':'' ?>>Sem responsável</option><?php foreach($assignees as $person): ?><option value="<?= (int)$person['id'] ?>" <?= (string)($filters['responsible']??'')===(string)$person['id']?'selected':'' ?>><?= $this->e((string)$person['name']) ?></option><?php endforeach; ?></select></label><label class="erp-filter-check"><input type="checkbox" name="overdue" value="1" <?= ($filters['overdue']??'')==='1'?'checked':'' ?>>Atrasadas</label><button class="erp-button erp-button-primary" type="submit">Filtrar</button></form>
<?php if($tasks===[]): ?><div class="erp-empty-state"><strong>Nenhuma pendência encontrada</strong><p>Condomínios sem CNPJ válido aparecem aqui automaticamente.</p></div><?php else: ?><div class="erp-table-wrap"><table class="erp-responsive-directory-table"><thead><tr><th>Condomínio</th><th>Responsável</th><th>Status</th><th>Prioridade</th><th>Prazo operacional</th><th>Idade</th></tr></thead><tbody><?php foreach($tasks as $task): ?><tr><td data-label="Condomínio"><a class="erp-record-link" href="/erp/pending/<?= (int)$task['id'] ?>"><?= $this->e((string)$task['condominium_name']) ?></a></td><td data-label="Responsável"><?= $this->e((string)($task['responsible_name']??'Sem responsável')) ?></td><td data-label="Status"><?= $task['status']==='in_progress'?'Em andamento':($task['status']==='done'?'Resolvida':'Pendente') ?></td><td data-label="Prioridade"><?= $this->e((string)$task['priority']) ?></td><td data-label="Prazo operacional"><?= $this->e((string)($task['due_at']?date('d/m/Y',strtotime((string)$task['due_at'])):'Sem prazo')) ?></td><td data-label="Idade"><?= max(0,(int)(new DateTimeImmutable((string)$task['created_at']))->diff(new DateTimeImmutable('today'))->days) ?> dia(s)</td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main>
